export const forgotPasswordRoutePath = 'forgot';
export const resetPasswordRoutePath = 'reset';
export const signupRoutePath = 'sign-up';
export const verseRoutePath = 'verse';
export const accountRoutePath = 'account';
export const publicRoutePath = 'public';
export const toolsRoutePath = 'tools';
export const settingsRoutePath = 'settings';
type RoutePath =
  | typeof favoritesRoutePath
  | typeof profileRoutePath
  | typeof searchRoutePath
  | typeof loginRoutePath
  | typeof signupRoutePath
  | typeof loginEmailRoutePath
  | typeof forgotPasswordRoutePath
  | typeof resetPasswordRoutePath
  | typeof verseRoutePath
  | typeof accountRoutePath
  | typeof publicRoutePath
  | typeof toolsRoutePath
  | typeof settingsRoutePath;

export function getRoutePath(routePath: RoutePath) {
  return `/${routePath}`;
}

export function getFavoritesRoutePath(path?: typeof verseRoutePath) {
  if (!path) {
    return getRoutePath(favoritesRoutePath);
  }

  return `${getRoutePath(favoritesRoutePath)}/${path}`;
}

export function getSearchRoutePath(path?: typeof verseRoutePath) {
  if (!path) {
    return getRoutePath(searchRoutePath);
  }

  return `${getRoutePath(searchRoutePath)}/${path}`;
}

export function getLoginRoutePath(
  path?: typeof loginEmailRoutePath | typeof forgotPasswordRoutePath
) {
  if (!path) {
    return getRoutePath(loginRoutePath);
  }

  return `${getRoutePath(loginRoutePath)}/${path}`;
}

